--
-- Name: calculer_prix(integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculer_prix(p_id_tarif integer, p_quantite numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prix NUMERIC := 0;
    v_debut NUMERIC;
    v_fin NUMERIC;
    v_prix_unitaire NUMERIC;
BEGIN
    FOR v_debut, v_fin, v_prix_unitaire IN
        SELECT t.v_debut, t.v_fin, t.prix
        FROM tranche t
        WHERE t.id_tarif = p_id_tarif
        ORDER BY t.v_debut
    LOOP

        IF p_quantite > v_debut THEN

            IF v_fin IS NULL THEN
                v_prix := v_prix
                    + (p_quantite - v_debut) * v_prix_unitaire;

            ELSE
                v_prix := v_prix
                    + (LEAST(p_quantite, v_fin) - v_debut)
                    * v_prix_unitaire;
            END IF;

        END IF;

    END LOOP;

    RETURN ROUND(v_prix, 3);
END;
$$;


